Lemma novalign_clip : forall dx sx, - 2^16 <= dx <= 2^16 -> - 2^16 <= sx <= 2^16 -> rop_novalign dx sx ->
  let sx1 := sx - Z.min dx 0 in let DX := Z.max dx 0 - Z.min sx1 0 in let SX := Z.max sx1 0 in
